/// Returns true if `n` is an exact power of two (…1, 2, 4, 8, …), false otherwise.
pub fn is_2_pow(n: i32) -> bool {
    n > 0 && (n & (n - 1)) == 0
}

/// A standard lower‐bound binary search on the slice `a` in the half-open range [lo, hi).
/// Returns the smallest `k` in `[lo, hi]` such that for all `r < k`, `a[r] < x`,
/// and for all `r >= k` (and `r < hi`), `a[r] >= x`.
pub fn search_range_helper(a: &[i32], x: i32, mut lo: usize, mut hi: usize) -> usize {
    debug_assert!(lo <= hi);
    debug_assert!(hi <= a.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if a[mid] < x {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

/// Special case: compute the lower bound of `x` in the first 1000 elements of `a`.
/// It returns an index `k` in `0..=1000` such that
///   - for every `r < k`, `a[r] < x`,
///   - for every `k <= r < 1000`, `a[r] >= x`.
/// Panics if `a.len() < 1000`.
pub fn search_1000(a: &[i32], x: i32) -> usize {
    // We only consider positions 0..1000.
    assert!(a.len() >= 1000, "array must have at least 1000 elements");
    search_range_helper(a, x, 0, 1000)
}

